      Let Hfd1 : forall mo, HeapMF_iface.hs_MPRES HM moH mo -> fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)).
      Proof. intros mo MP. destruct (hm_mpres HM HXM _ _ MP) as [_ Ef]. rewrite Ef, (proj2 MOH). exact (tr_fd1 _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let Hfd2 : forall mo, HeapMF_iface.hs_MPRES HM moH mo -> fd_lookup (m_fds mo) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)).
      Proof. intros mo MP. destruct (hm_mpres HM HXM _ _ MP) as [_ Ef]. rewrite Ef, (proj2 MOH). exact (tr_fd2 _ _ _ _ _ _ _ _ _ _ PRE). Qed.

      (* [comment removed for export] *)
      Lemma tr_post : forall (fxc : FPState) regs' mem' mo sC,
        getr regs' 2 = sp -> getr regs' 4 = Z_to_bv 64 0x10b6b8 -> getr regs' 10 = Z_to_bv 64 0 ->
        getr regs' 8 = getr regs0 8 -> getr regs' 9 = getr regs0 9 -> getr regs' 18 = getr regs0 18 -> getr regs' 19 = getr regs0 19 ->
        getr regs' 20 = getr regs0 20 -> getr regs' 21 = getr regs0 21 -> getr regs' 22 = getr regs0 22 -> getr regs' 23 = getr regs0 23 ->
        (forall rr : reg, In rr ([24; 25; 26; 27]%bv : list reg) -> getr regs' rr = getr regs0 rr) ->
        tinv mem' -> HeapMF_iface.hs_RHEAP HM sC LB mem' -> HeapMF_iface.hs_KREL HM sC mo -> HeapMF_iface.hs_MPRES HM moH mo ->
        (exists B', HeapMF_iface.hs_rauxv_ok HM mem' B' /\ bv_unsigned sp + 128 <= B' < 2 ^ 64) ->
        sto calls mem' -> ax1_reads mem' -> rdn RSEGS mem' (Z_to_bv 64 0x109c04) 1 = Some (word_to_le_bytes 1 (Z_to_bv 64 0)) ->
        realizes RSEGS (mkCfg (@mkst fxc regs' (Z_to_bv 64 0x47544) mem' (seg_rom RSEGS)) mo) K.
