      (* [comment removed for export] *)
      Lemma tr_ret : forall (fxc : FPState) regs m mo sC,
        getr regs 2 = Z_to_bv 64 (bv_unsigned sp - 80) -> getr regs 4 = Z_to_bv 64 0x10b6b8 -> getr regs 20 = Z_to_bv 64 0x109c00 ->
        getr regs 22 = Z_to_bv 64 0 -> getr regs 23 = Z_to_bv 64 (-2) ->
        (forall rr : reg, In rr ([24; 25; 26; 27]%bv : list reg) -> getr regs rr = getr regs0 rr) ->
        tinv m -> tframe sp m (getr regs0 8) (getr regs0 9) (getr regs0 18) (getr regs0 19) (getr regs0 20) (getr regs0 21) (getr regs0 22) (getr regs0 23) ->
        HeapMF_iface.hs_RHEAP HM sC LB m -> HeapMF_iface.hs_KREL HM sC mo -> HeapMF_iface.hs_MPRES HM moH mo ->
        (exists B', HeapMF_iface.hs_rauxv_ok HM m B' /\ bv_unsigned sp + 128 <= B' < 2 ^ 64) ->
        sto calls m -> ax1_reads m -> rdn RSEGS m (Z_to_bv 64 0x109c04) 1 = Some (word_to_le_bytes 1 (Z_to_bv 64 0)) ->
